import { createHmac, timingSafeEqual } from "node:crypto";

type ConfirmationAction = "confirm" | "cancel";

type ConfirmationPayload = {
  bookingId: string;
  action: ConfirmationAction;
  exp: number;
};

function getSecret(): string {
  const secret = process.env.BOOKING_CONFIRMATION_SECRET?.trim();
  if (!secret) {
    throw new Error("Missing BOOKING_CONFIRMATION_SECRET. Set it to enable booking confirmations.");
  }
  return secret;
}

function signPayload(payload: ConfirmationPayload): string {
  const base = `${payload.bookingId}.${payload.action}.${payload.exp}`;
  return createHmac("sha256", getSecret()).update(base).digest("hex");
}

export function createBookingConfirmationLink(input: {
  bookingId: string;
  action: ConfirmationAction;
  baseUrl?: string;
  expiresInSeconds?: number;
}): string {
  const baseUrl = (input.baseUrl || process.env.NEXT_PUBLIC_SITE_URL || "https://ocupaloc.ro").replace(/\/$/, "");
  const exp = Math.floor(Date.now() / 1000) + (input.expiresInSeconds ?? 60 * 60 * 24 * 14);
  const sig = signPayload({ bookingId: input.bookingId, action: input.action, exp });
  const params = new URLSearchParams({
    booking: input.bookingId,
    action: input.action,
    exp: String(exp),
    sig
  });
  return `${baseUrl}/api/programare/confirmare?${params.toString()}`;
}

export function verifyBookingConfirmationLink(input: {
  bookingId: string;
  action: string;
  exp: string;
  sig: string;
}): { ok: true; action: ConfirmationAction } | { ok: false; message: string } {
  const action = input.action === "confirm" || input.action === "cancel" ? input.action : null;
  if (!action) {
    return { ok: false, message: "Acțiune invalidă." };
  }

  const expNum = Number(input.exp);
  if (!Number.isFinite(expNum) || expNum <= 0) {
    return { ok: false, message: "Token invalid." };
  }

  if (Math.floor(Date.now() / 1000) > expNum) {
    return { ok: false, message: "Link expirat." };
  }

  const expected = signPayload({ bookingId: input.bookingId, action, exp: expNum });
  try {
    const a = Buffer.from(expected, "utf8");
    const b = Buffer.from(input.sig, "utf8");
    if (a.length !== b.length || !timingSafeEqual(a, b)) {
      return { ok: false, message: "Semnătură invalidă." };
    }
  } catch {
    return { ok: false, message: "Semnătură invalidă." };
  }

  return { ok: true, action };
}

import type { SupabaseClient } from "@supabase/supabase-js";

import { createSupabaseServiceClient } from "@/lib/supabase/admin";

export type EmailQueueItem = {
  id: string;
  template: string;
  to_email: string;
  subject: string;
  payload: Record<string, unknown>;
  status: "queued" | "processing" | "sent" | "failed";
  retry_count: number;
  next_retry_at: string;
  last_error: string | null;
  created_at: string;
  updated_at: string;
  sent_at: string | null;
};

function resolveAdmin(admin?: SupabaseClient): SupabaseClient {
  return admin ?? createSupabaseServiceClient();
}

export async function enqueueEmail(
  input: {
    template: string;
    toEmail: string;
    subject: string;
    payload: Record<string, unknown>;
  },
  admin?: SupabaseClient
): Promise<void> {
  const db = resolveAdmin(admin);
  const { error } = await db.from("email_queue").insert({
    template: input.template,
    to_email: input.toEmail,
    subject: input.subject,
    payload: input.payload,
    status: "queued",
    retry_count: 0,
    next_retry_at: new Date().toISOString()
  });

  if (error) {
    throw new Error(`email_queue enqueue failed: ${error.message}`);
  }
}

export async function claimQueuedEmails(limit: number, admin?: SupabaseClient): Promise<EmailQueueItem[]> {
  const db = resolveAdmin(admin);
  const { data, error } = await db.rpc("claim_email_queue_items", { p_limit: limit });

  if (error) {
    throw new Error(`email_queue claim failed: ${error.message}`);
  }

  return (data as EmailQueueItem[] | null) ?? [];
}

export async function markEmailSent(id: string, admin?: SupabaseClient): Promise<void> {
  const db = resolveAdmin(admin);
  const { error } = await db
    .from("email_queue")
    .update({
      status: "sent",
      sent_at: new Date().toISOString(),
      last_error: null,
      updated_at: new Date().toISOString()
    })
    .eq("id", id);

  if (error) {
    throw new Error(`email_queue mark sent failed: ${error.message}`);
  }
}

function getBackoffMinutes(retryCount: number): number | null {
  if (retryCount === 1) return 5;
  if (retryCount === 2) return 15;
  if (retryCount === 3) return 60;
  return null;
}

export async function markEmailFailed(id: string, retryCount: number, errorMessage: string, admin?: SupabaseClient): Promise<void> {
  const db = resolveAdmin(admin);
  const nextRetryCount = retryCount + 1;
  const backoffMinutes = getBackoffMinutes(nextRetryCount);

  if (!backoffMinutes) {
    const { error } = await db
      .from("email_queue")
      .update({
        status: "failed",
        retry_count: nextRetryCount,
        last_error: errorMessage.slice(0, 1000),
        updated_at: new Date().toISOString()
      })
      .eq("id", id);

    if (error) {
      throw new Error(`email_queue mark final failed failed: ${error.message}`);
    }

    return;
  }

  const nextRetry = new Date(Date.now() + backoffMinutes * 60 * 1000).toISOString();
  const { error } = await db
    .from("email_queue")
    .update({
      status: "queued",
      retry_count: nextRetryCount,
      next_retry_at: nextRetry,
      last_error: errorMessage.slice(0, 1000),
      updated_at: new Date().toISOString()
    })
    .eq("id", id);

  if (error) {
    throw new Error(`email_queue requeue failed: ${error.message}`);
  }
}

