  /**
   * Creates a new Iceberg REST Catalog client.
   *
   * @param options - Configuration options for the catalog client
   */
  constructor(options: IcebergRestCatalogOptions) {
    let prefix = 'v1'
    if (options.catalogName) {
      prefix += `/${options.catalogName}`
    }

    const baseUrl = options.baseUrl.endsWith('/') ? options.baseUrl : `${options.baseUrl}/`

    this.client = createFetchClient({
      baseUrl,
      auth: options.auth,
      fetchImpl: options.fetch,
    })

    // Format accessDelegation as comma-separated string per spec
    this.accessDelegation = options.accessDelegation?.join(',')

    this.namespaceOps = new NamespaceOperations(this.client, prefix)
    this.tableOps = new TableOperations(this.client, prefix, this.accessDelegation)
  }

  /**
   * Lists all namespaces in the catalog.
   *
   * @param parent - Optional parent namespace to list children under
   * @returns Array of namespace identifiers
   *
   * @example
   * ```typescript
   * // List all top-level namespaces
   * const namespaces = await catalog.listNamespaces();
   *
   * // List namespaces under a parent
   * const children = await catalog.listNamespaces({ namespace: ['analytics'] });
   * ```
   */
  async listNamespaces(parent?: NamespaceIdentifier): Promise<NamespaceIdentifier[]> {
    return this.namespaceOps.listNamespaces(parent)
  }

  /**
   * Creates a new namespace in the catalog.
   *
   * @param id - Namespace identifier to create
   * @param metadata - Optional metadata properties for the namespace
   * @returns Response containing the created namespace and its properties
   *
   * @example
   * ```typescript
   * const response = await catalog.createNamespace(
   *   { namespace: ['analytics'] },
   *   { properties: { owner: 'data-team' } }
   * );
   * console.log(response.namespace); // ['analytics']
   * console.log(response.properties); // { owner: 'data-team', ... }
   * ```
   */
  async createNamespace(id: NamespaceIdentifier, metadata?: NamespaceMetadata): Promise<CreateNamespaceResponse> {
    return this.namespaceOps.createNamespace(id, metadata)
  }

  /**
   * Drops a namespace from the catalog.
   *
   * The namespace must be empty (contain no tables) before it can be dropped.
   *
   * @param id - Namespace identifier to drop
   *
   * @example
   * ```typescript
   * await catalog.dropNamespace({ namespace: ['analytics'] });
   * ```
   */
  async dropNamespace(id: NamespaceIdentifier): Promise<void> {
    await this.namespaceOps.dropNamespace(id)
  }

  /**
   * Loads metadata for a namespace.
   *
   * @param id - Namespace identifier to load
   * @returns Namespace metadata including properties
   *
   * @example
   * ```typescript
   * const metadata = await catalog.loadNamespaceMetadata({ namespace: ['analytics'] });
   * console.log(metadata.properties);
   * ```
   */
  async loadNamespaceMetadata(id: NamespaceIdentifier): Promise<NamespaceMetadata> {
    return this.namespaceOps.loadNamespaceMetadata(id)
  }

  /**
   * Lists all tables in a namespace.
   *
   * @param namespace - Namespace identifier to list tables from
   * @returns Array of table identifiers
   *
   * @example
   * ```typescript
   * const tables = await catalog.listTables({ namespace: ['analytics'] });
   * console.log(tables); // [{ namespace: ['analytics'], name: 'events' }, ...]
   * ```
   */
  async listTables(namespace: NamespaceIdentifier): Promise<TableIdentifier[]> {
    return this.tableOps.listTables(namespace)
  }

  /**
   * Creates a new table in the catalog.
   *
   * @param namespace - Namespace to create the table in
   * @param request - Table creation request including name, schema, partition spec, etc.
   * @returns Table metadata for the created table
   *
   * @example
   * ```typescript
   * const metadata = await catalog.createTable(
   *   { namespace: ['analytics'] },
   *   {
   *     name: 'events',
   *     schema: {
   *       type: 'struct',
   *       fields: [
   *         { id: 1, name: 'id', type: 'long', required: true },
   *         { id: 2, name: 'timestamp', type: 'timestamp', required: true }
   *       ],
   *       'schema-id': 0
   *     },
   *     'partition-spec': {
   *       'spec-id': 0,
   *       fields: [
   *         { source_id: 2, field_id: 1000, name: 'ts_day', transform: 'day' }
   *       ]
   *     }
   *   }
   * );
   * ```
   */
  async createTable(
    namespace: NamespaceIdentifier,
    request: CreateTableRequest
  ): Promise<TableMetadata> {
    return this.tableOps.createTable(namespace, request)
  }

  /**
   * Updates an existing table's metadata.
   *
   * Can update the schema, partition spec, or properties of a table.
   *
   * @param id - Table identifier to update
   * @param request - Update request with fields to modify
   * @returns Response containing the metadata location and updated table metadata
   *
   * @example
   * ```typescript
   * const response = await catalog.updateTable(
   *   { namespace: ['analytics'], name: 'events' },
   *   {
   *     properties: { 'read.split.target-size': '134217728' }
   *   }
   * );
   * console.log(response['metadata-location']); // s3://...
   * console.log(response.metadata); // TableMetadata object
   * ```
   */
  async updateTable(id: TableIdentifier, request: UpdateTableRequest): Promise<CommitTableResponse> {
    return this.tableOps.updateTable(id, request)
  }

  /**
   * Drops a table from the catalog.
   *
   * @param id - Table identifier to drop
   *
   * @example
   * ```typescript
   * await catalog.dropTable({ namespace: ['analytics'], name: 'events' });
   * ```
   */
  async dropTable(id: TableIdentifier, options?: DropTableRequest): Promise<void> {
    await this.tableOps.dropTable(id, options)
  }

  /**
   * Loads metadata for a table.
   *
   * @param id - Table identifier to load
   * @returns Table metadata including schema, partition spec, location, etc.
   *
   * @example
   * ```typescript
   * const metadata = await catalog.loadTable({ namespace: ['analytics'], name: 'events' });
   * console.log(metadata.schema);
   * console.log(metadata.location);
   * ```
   */
  async loadTable(id: TableIdentifier): Promise<TableMetadata> {
    return this.tableOps.loadTable(id)
  }

  /**
   * Checks if a namespace exists in the catalog.
   *
   * @param id - Namespace identifier to check
   * @returns True if the namespace exists, false otherwise
   *
   * @example
   * ```typescript
   * const exists = await catalog.namespaceExists({ namespace: ['analytics'] });
   * console.log(exists); // true or false
   * ```
   */
  async namespaceExists(id: NamespaceIdentifier): Promise<boolean> {
    return this.namespaceOps.namespaceExists(id)
  }

  /**
   * Checks if a table exists in the catalog.
   *
   * @param id - Table identifier to check
   * @returns True if the table exists, false otherwise
   *
   * @example
   * ```typescript
   * const exists = await catalog.tableExists({ namespace: ['analytics'], name: 'events' });
   * console.log(exists); // true or false
   * ```
   */
  async tableExists(id: TableIdentifier): Promise<boolean> {
    return this.tableOps.tableExists(id)
  }

  /**
   * Creates a namespace if it does not exist.
   *
   * If the namespace already exists, returns void. If created, returns the response.
   *
   * @param id - Namespace identifier to create
   * @param metadata - Optional metadata properties for the namespace
   * @returns Response containing the created namespace and its properties, or void if it already exists
   *
   * @example
   * ```typescript
   * const response = await catalog.createNamespaceIfNotExists(
   *   { namespace: ['analytics'] },
   *   { properties: { owner: 'data-team' } }
   * );
   * if (response) {
   *   console.log('Created:', response.namespace);
   * } else {
   *   console.log('Already exists');
   * }
   * ```
   */
  async createNamespaceIfNotExists(
    id: NamespaceIdentifier,
    metadata?: NamespaceMetadata
  ): Promise<CreateNamespaceResponse | void> {
    return this.namespaceOps.createNamespaceIfNotExists(id, metadata)
  }

  /**
   * Creates a table if it does not exist.
   *
   * If the table already exists, returns its metadata instead.
   *
   * @param namespace - Namespace to create the table in
   * @param request - Table creation request including name, schema, partition spec, etc.
   * @returns Table metadata for the created or existing table
   *
   * @example
   * ```typescript
   * const metadata = await catalog.createTableIfNotExists(
   *   { namespace: ['analytics'] },
   *   {
   *     name: 'events',
   *     schema: {
   *       type: 'struct',
   *       fields: [
   *         { id: 1, name: 'id', type: 'long', required: true },
   *         { id: 2, name: 'timestamp', type: 'timestamp', required: true }
   *       ],
   *       'schema-id': 0
   *     }
   *   }
   * );
   * ```
   */
  async createTableIfNotExists(
    namespace: NamespaceIdentifier,
    request: CreateTableRequest
  ): Promise<TableMetadata> {
    return this.tableOps.createTableIfNotExists(namespace, request)
  }
}
export interface NamespaceIdentifier {
  namespace: string[]
}

export interface NamespaceMetadata {
  properties: Record<string, string>
}

export interface TableIdentifier {
  namespace: string[]
  name: string
}

/**
 * Primitive types in Iceberg - all represented as strings.
 * Parameterized types use string format: decimal(precision,scale) and fixed[length]
 *
 * Note: The OpenAPI spec defines PrimitiveType as `type: string`, so any string is valid.
 * We include known types for autocomplete, plus a catch-all for flexibility.
 */
export type PrimitiveType =
  | 'boolean'
  | 'int'
  | 'long'
  | 'float'
  | 'double'
  | 'string'
  | 'timestamp'
  | 'date'
  | 'time'
  | 'timestamptz'
  | 'uuid'
  | 'binary'
  | `decimal(${number},${number})`
  | `fixed[${number}]`
  | (string & {}) // catch-all for any format (e.g., "decimal(10, 2)" with spaces) and future types

/**
 * Regex patterns for parsing parameterized types.
 * These allow flexible whitespace matching.
 */
const DECIMAL_REGEX = /^decimal\s*\(\s*(\d+)\s*,\s*(\d+)\s*\)$/
const FIXED_REGEX = /^fixed\s*\[\s*(\d+)\s*\]$/

/**
 * Parse a decimal type string into its components.
 * Handles any whitespace formatting (e.g., "decimal(10,2)", "decimal(10, 2)", "decimal( 10 , 2 )").
 *
 * @param type - The type string to parse
 * @returns Object with precision and scale, or null if not a valid decimal type
 */
export function parseDecimalType(type: string): { precision: number; scale: number } | null {
  const match = type.match(DECIMAL_REGEX)
  if (!match) return null
  return {
    precision: parseInt(match[1], 10),
    scale: parseInt(match[2], 10),
  }
}

/**
 * Parse a fixed type string into its length.
 * Handles any whitespace formatting (e.g., "fixed[16]", "fixed[ 16 ]").
 *
 * @param type - The type string to parse
 * @returns Object with length, or null if not a valid fixed type
 */
export function parseFixedType(type: string): { length: number } | null {
  const match = type.match(FIXED_REGEX)
  if (!match) return null
  return {
    length: parseInt(match[1], 10),
  }
}

/**
 * Check if a type string is a decimal type.
 */
export function isDecimalType(type: string): boolean {
  return DECIMAL_REGEX.test(type)
}

/**
 * Check if a type string is a fixed type.
 */
export function isFixedType(type: string): boolean {
  return FIXED_REGEX.test(type)
}

/**
 * Compare two Iceberg type strings for equality, ignoring whitespace differences.
 * This is useful when comparing types from user input vs catalog responses,
 * as catalogs may normalize whitespace differently.
 *
 * @param a - First type string
 * @param b - Second type string
 * @returns true if the types are equivalent
 */
export function typesEqual(a: string, b: string): boolean {
  // For decimal types, compare parsed values
  const decimalA = parseDecimalType(a)
  const decimalB = parseDecimalType(b)
  if (decimalA && decimalB) {
    return decimalA.precision === decimalB.precision && decimalA.scale === decimalB.scale
  }

  // For fixed types, compare parsed values
  const fixedA = parseFixedType(a)
  const fixedB = parseFixedType(b)
  if (fixedA && fixedB) {
    return fixedA.length === fixedB.length
  }

  // For other types, direct string comparison
  return a === b
}

/**
 * Struct type - a nested structure containing fields.
 * Used for nested records within a field.
 */
export interface StructType {
  type: 'struct'
  fields: StructField[]
}

/**
 * List type - an array of elements.
 */
export interface ListType {
  type: 'list'
  'element-id': number
  element: IcebergType
  'element-required': boolean
}

/**
 * Map type - a key-value mapping.
 */
export interface MapType {
  type: 'map'
  'key-id': number
  key: IcebergType
  'value-id': number
  value: IcebergType
  'value-required': boolean
}

/**
 * Union of all Iceberg types.
 * Can be a primitive type (string) or a complex type (struct, list, map).
 */
export type IcebergType = PrimitiveType | StructType | ListType | MapType

/**
 * Primitive type values for default values.
 * Represents the possible values for initial-default and write-default.
 */
export type PrimitiveTypeValue = boolean | number | string

/**
 * A field within a struct (used in nested StructType).
 */
export interface StructField {
  id: number
  name: string
  type: IcebergType
  required: boolean
  doc?: string
  'initial-default'?: PrimitiveTypeValue
  'write-default'?: PrimitiveTypeValue
}

/**
 * A field within a table schema (top-level).
 * Equivalent to StructField but kept for backwards compatibility.
 */
export interface TableField {
  id: number
  name: string
  type: IcebergType
  required: boolean
  doc?: string
  'initial-default'?: PrimitiveTypeValue
  'write-default'?: PrimitiveTypeValue
}

export interface TableSchema {
  type: 'struct'
  fields: TableField[]
  'schema-id'?: number
  'identifier-field-ids'?: number[]
}

export interface PartitionField {
  source_id: number
  field_id: number
  name: string
  transform: string
}

export interface PartitionSpec {
  'spec-id': number
  fields: PartitionField[]
}

export interface SortField {
  source_id: number
  transform: string
  direction: 'asc' | 'desc'
  null_order: 'nulls-first' | 'nulls-last'
}

export interface SortOrder {
  'order-id': number
  fields: SortField[]
}

export interface CreateTableRequest {
  name: string
  schema: TableSchema
  'partition-spec'?: PartitionSpec
  'write-order'?: SortOrder
  properties?: Record<string, string>
  'stage-create'?: boolean
}

export interface UpdateTableRequest {
  schema?: TableSchema
  'partition-spec'?: PartitionSpec
  properties?: Record<string, string>
}

export interface DropTableRequest {
  purge?: boolean
}

export interface TableMetadata {
  name?: string
  location: string
  schemas: TableSchema[]
  'current-schema-id': number
  'partition-specs': PartitionSpec[]
  'default-spec-id'?: number
  'sort-orders': SortOrder[]
  'default-sort-order-id'?: number
  properties: Record<string, string>
  'metadata-location'?: string
  'current-snapshot-id'?: number
  snapshots?: unknown[]
  'snapshot-log'?: unknown[]
  'metadata-log'?: unknown[]
  refs?: Record<string, unknown>
  'last-updated-ms'?: number
  'last-column-id'?: number
  'last-sequence-number'?: number
  'table-uuid'?: string
  'format-version'?: number
  'last-partition-id'?: number
}

export interface CreateNamespaceRequest {
  namespace: string[]
  properties?: Record<string, string>
}

export interface CreateNamespaceResponse {
  namespace: string[]
  properties?: Record<string, string>
}

export interface GetNamespaceResponse {
  namespace: string[]
  properties: Record<string, string>
}

export interface ListNamespacesResponse {
  namespaces: string[][]
  'next-page-token'?: string
}

export interface ListTablesResponse {
  identifiers: TableIdentifier[]
  'next-page-token'?: string
}

export interface LoadTableResponse {
  'metadata-location': string
  metadata: TableMetadata
  config?: Record<string, string>
}

export interface CommitTableResponse {
  'metadata-location': string
  metadata: TableMetadata
}

/**
 * Gets the current (active) schema from table metadata.
 *
 * @param metadata - Table metadata containing schemas array and current-schema-id
 * @returns The current table schema, or undefined if not found
 */
export function getCurrentSchema(metadata: TableMetadata): TableSchema | undefined {
  return metadata.schemas.find((s) => s['schema-id'] === metadata['current-schema-id'])
}

const CRITICAL_SERVER_KEYS = [
  "NEXT_PUBLIC_SUPABASE_URL",
  "SUPABASE_SERVICE_ROLE_KEY",
  "STRIPE_WEBHOOK_SECRET",
  "RESEND_API_KEY",
  "RESEND_FROM",
  "REMINDERS_CRON_SECRET"
] as const;

export type EnvKey =
  | "NEXT_PUBLIC_SUPABASE_URL"
  | "SUPABASE_SERVICE_ROLE_KEY"
  | "STRIPE_WEBHOOK_SECRET"
  | "RESEND_API_KEY"
  | "RESEND_FROM"
  | "REMINDERS_CRON_SECRET"
  | "STRIPE_PRICE_ID"
  | "NEXT_PUBLIC_SITE_URL"
  | "BILLING_ENABLED";

function readRaw(key: string): string | undefined {
  const value = process.env[key];
  if (!value) {
    return undefined;
  }

  const trimmed = value.trim();
  return trimmed.length > 0 ? trimmed : undefined;
}

export function getEnv(key: EnvKey): string {
  const value = readRaw(key);
  if (!value) {
    throw new Error(`Missing ${key}`);
  }
  return value;
}

export function getOptionalEnv(key: EnvKey): string | undefined {
  return readRaw(key);
}

export function assertCriticalServerEnv(): void {
  for (const key of CRITICAL_SERVER_KEYS) {
    getEnv(key);
  }
}

export const env = {
  get: getEnv,
  optional: getOptionalEnv,
  assertCriticalServerEnv
};

import { env } from "@/lib/config/env";

export async function sendResendEmail(input: {
  to: string[];
  subject: string;
  text: string;
  html?: string;
  event: string;
  context?: Record<string, unknown>;
}): Promise<void> {
  const apiKey = env.get("RESEND_API_KEY");
  const from = env.get("RESEND_FROM");

  const res = await fetch("https://api.resend.com/emails", {
    method: "POST",
    headers: {
      Authorization: `Bearer ${apiKey}`,
      "Content-Type": "application/json"
    },
    body: JSON.stringify({
      from,
      to: input.to,
      subject: input.subject,
      text: input.text,
      html: input.html
    })
  });

  if (!res.ok) {
    const body = await res.text().catch(() => "");
    throw new Error(`Resend ${res.status}: ${body || input.event}`);
  }
}

type CriticalFlow = "booking" | "email" | "cron" | "auth" | "billing";

import { logError } from "@/lib/logger";
import { sendOpsAlert } from "@/lib/ops-alerting";

function serializeError(error: unknown): Record<string, unknown> {
  if (error instanceof Error) {
    return {
      name: error.name,
      message: error.message,
      stack: error.stack
    };
  }

  return {
    value: String(error)
  };
}

export function reportError(
  flow: CriticalFlow,
  event: string,
  error: unknown,
  context?: Record<string, unknown>
): void {
  const payload = {
    level: "error",
    flow,
    event,
    context: context ?? {},
    error: serializeError(error),
    timestamp: new Date().toISOString()
  };

  logError("[observability] reportError", error, {
    flow,
    event,
    requestId: typeof context?.requestId === "string" ? context.requestId : undefined
  });

  void sendOpsAlert({
    flow,
    event,
    context: payload.context,
    error: payload.error,
    timestamp: payload.timestamp
  });

  // Forward to Sentry when configured (non-blocking)
  if (process.env.SENTRY_DSN) {
    void import("@sentry/nextjs")
      .then(({ withScope, captureException }) => {
        withScope((scope) => {
          scope.setTag("flow", flow);
          scope.setTag("event", event);
          scope.setExtras(context ?? {});
          captureException(error instanceof Error ? error : new Error(String(error)));
        });
      })
      .catch(() => {
        // Sentry unavailable — already logged to console above
      });
  }
}

/**
 * Structured JSON logger — single file, no dependencies, no Sentry.
 * All logs output as JSON to console for easy aggregation in production.
 *
 * Sentry error capture remains in observability.ts reportError().
 */

import { randomUUID } from 'crypto';

export interface LogEntry {
  timestamp: string;
  level: 'error' | 'warn' | 'info';
  message: string;
  error?: {
    name?: string;
    message?: string;
    code?: string;
    statusCode?: number;
  };
  context?: Record<string, string | number | boolean | null | undefined>;
}

function normalizeError(error: unknown): LogEntry['error'] | undefined {
  if (!error) return undefined;

  if (error instanceof Error) {
    const entry: LogEntry['error'] = {
      name: error.name,
      message: error.message,
    };

    // Include custom fields if attached
    if ('code' in error && typeof error.code === 'string') {
      entry.code = error.code;
    }
    if ('statusCode' in error && typeof error.statusCode === 'number') {
      entry.statusCode = error.statusCode;
    }

    return entry;
  }

  return { message: String(error) };
}

/**
 * Internal function: output a log entry.
 * Uses console.error for all levels so they're visible in production logs.
 */
function output(entry: LogEntry): void {
  console.error(JSON.stringify(entry));
}

/**
 * Log an error with optional error object and context.
 */
export function logError(
  message: string,
  error?: unknown,
  context?: Record<string, string | number | boolean | null | undefined>
): void {
  output({
    timestamp: new Date().toISOString(),
    level: 'error',
    message,
    error: normalizeError(error),
    context,
  });
}

/**
 * Log a warning (e.g., rate limit exceeded, client blocked).
 * Error object is optional.
 */
export function logWarn(
  message: string,
  context?: Record<string, string | number | boolean | null | undefined>,
  error?: unknown
): void {
  output({
    timestamp: new Date().toISOString(),
    level: 'warn',
    message,
    error: error ? normalizeError(error) : undefined,
    context,
  });
}

/**
 * Log informational message.
 */
export function logInfo(
  message: string,
  context?: Record<string, string | number | boolean | null | undefined>
): void {
  output({
    timestamp: new Date().toISOString(),
    level: 'info',
    message,
    context,
  });
}

/**
 * Extract request ID from headers, or generate a new one.
 * Simple helper, no async context needed.
 */
export function getRequestId(headers: Headers): string {
  return (
    headers.get('x-request-id')?.trim() ||
    headers.get('x-correlation-id')?.trim() ||
    randomUUID()
  );
}

type OpsAlertPayload = {
  flow: "booking" | "email" | "cron" | "auth" | "billing";
  event: string;
  context: Record<string, unknown>;
  error: Record<string, unknown>;
  timestamp: string;
};

let lastSentAt = 0;

export async function sendOpsAlert(payload: OpsAlertPayload): Promise<void> {
  const url = process.env.ALERT_WEBHOOK_URL?.trim();
  if (!url) {
    return;
  }

  const cooldownMs = Number(process.env.ALERT_COOLDOWN_MS ?? "300000");
  if (Number.isFinite(cooldownMs) && cooldownMs > 0) {
    const now = Date.now();
    if (now - lastSentAt < cooldownMs) {
      return;
    }
    lastSentAt = now;
  }

  const bearer = process.env.ALERT_WEBHOOK_BEARER_TOKEN?.trim();

  await fetch(url, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      ...(bearer ? { Authorization: `Bearer ${bearer}` } : {})
    },
    body: JSON.stringify(payload)
  }).catch(() => {
    // Best-effort alerting only.
  });
}
